package engine
import "../state"
begin :: proc(s: ^state.Store) -> bool {s.depth += 1; return true}
finish :: proc(s: ^state.Store) {s.depth -= 1}
set :: proc(s: ^state.Store) {s.value = 2}
publish :: proc(dst, src: ^state.Store, approved: bool) {assert(approved); dst^ = src^; src^ = {}}

consumer/consumer.odin:
package consumer
import "../src/state"
import "../src/engine"
live: state.Store
run :: proc() {
	work: state.Store
	if engine.begin(&live) {defer engine.finish(&live); engine.set(&live)}
	engine.publish(&live, &work, false)
}
